const panelIds=['help','bag','character','journal','relics','mapPanel','service','swords'];
function closePanels(){panelIds.forEach(id=>{if($(id).open)$(id).close()});keys={};}
function openPanel(id){if($(id).open){$(id).close();keys={};return}closePanels();refreshBag();if(id==='mapPanel'){drawMap();renderMapDestinations();}if(id==='swords')renderSwordCollection();if(id==='journal')renderJournal();if(id==='bag')$(id).show();else $(id).showModal();if(id==='bag'||id==='character')refreshBag();$(id).scrollTop=0;keys={};}
function refreshBag(){const count=Object.values(p.inventory).reduce((a,b)=>a+b,0);$('bagSummary').textContent=count+' eşya';$('equipment').textContent=`Kılıç +${p.weapon} · ${damage()} hasar | Zırh +${p.armor}`;$('villageGold').textContent=p.gold+' altın';$('hudWeapon').textContent=equippedSword().name+' +'+p.weapon;
 if($('bag').open)renderInventory();else renderQuickbar();
 if($('character').open){$('characterContents').innerHTML=`<div class="hero-showcase"><canvas id="heroPreview" width="210" height="220" aria-label="Yeni karakter ve kuşanılmış kılıç"></canvas><div><h3>Ocak Şövalyesi</h3><p>${equippedSword().name} +${p.weapon}</p><p class="fine">${equippedSword().effect}</p><button id="openSwords">Kılıçlar · K</button></div></div><div class="equip-row"><span>Seviye</span><b>${p.level}</b></div><div class="equip-row"><span>Can</span><b>${Math.ceil(p.hp)} / ${p.maxHp}</b></div><div class="equip-row"><span>⚔ ${equippedSword().name} +${p.weapon}</span><b>${damage()} hasar</b></div><div class="equip-row"><span>▣ Gezgin zırhı +${p.armor}</span><b>−${p.armor*2+(accessoryStats().armor||0)} alınan hasar</b></div><div class="equip-row"><span>Aksesuar</span><b>${ITEMS[p.accessory]?.name||'Kuşanılmamış'}</b></div><div class="equip-row"><span>Varg eğitimi +${p.training}</span><b>+${p.training*3} hasar</b></div><div class="equip-row"><span>Yadigâr</span><b>${{xp:'+%25 XP',gold:'+%25 altın',speed:'+%15 hız'}[p.boost]}</b></div><p class="fine">Güçlendirmek için Ocak Köyü’ndeki demirci Boran’a git.</p>`;$('openSwords').onclick=()=>openPanel('swords');}if($('swords').open)renderSwordCollection();
}
function drawMap(){const mc=$('mapCanvas'),m=mc.getContext('2d');m.fillStyle='#152f37';m.fillRect(0,0,560,380);const hub=p.area==='hub',w=hub?HUB.w:WORLD.w,h=hub?HUB.h:WORLD.h,sx=540/w,sy=350/h;
 if(hub){if(!villageFloor)makeVillageFloor();m.drawImage(villageFloor,10,15,540,350);services.forEach(s=>{m.fillStyle=s.color;m.fillRect(10+s.x*sx-3,15+s.y*sy-3,6,6);m.fillStyle='#fff0c8';m.font='9px monospace';m.textAlign='center';m.fillText(s.name,10+s.x*sx,15+s.y*sy+14)});}else{zones.forEach(z=>{m.fillStyle=z.color;m.fillRect(10+z.x*sx,15+z.y*sy,1920*sx,1280*sy);m.fillStyle='#e4e4be';m.font='11px monospace';m.textAlign='center';m.fillText(z.name,10+(z.x+960)*sx,15+(z.y+500)*sy)});m.fillStyle='#b7dcab';m.fillRect(10+280*sx-3,15+330*sy-3,6,6)}
 if(hub)POI.forEach(z=>{m.fillStyle='#b8b9a0';m.font='9px monospace';m.textAlign='center';m.fillText(z.name,10+z.x*sx,15+z.y*sy)});if(!hub)enemies.filter(e=>e.boss&&!e.dead).forEach(e=>{m.fillStyle='#e7a0a0';m.fillRect(8+e.x*sx,13+e.y*sy,6,6);m.font='8px monospace';m.fillText(e.name,10+e.x*sx,11+e.y*sy)});m.fillStyle='#fff0b3';m.beginPath();m.arc(10+p.x*sx,15+p.y*sy,4,0,7);m.fill();m.strokeStyle='#302d41';m.lineWidth=1;m.stroke();$('mapTitle').textContent=hub?'Ocak Köyü':'Zindan 01 · Fısıltılı Orman';$('mapLegend').textContent=hub?'● Sen · 7 uzman köylü · Doğu: orman / Batı: mahzen / Güneydoğu: arena':'● Sen · Kuzeybatıdaki geçit köye döner. R ile de köye dönebilirsin.';
}
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(e.ctrlKey||e.metaKey||e.altKey)return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName)&&key!=='escape')return;const binds={b:'bag',c:'bag',j:'journal',n:'relics',m:'mapPanel',h:'help',k:'swords'};if(/^[1-5]$/.test(key)){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat){if($('bag').open){if(quickAssignItem)commitQuickSlot(Number(key)-1,quickAssignItem);else openQuickPicker(Number(key)-1)}else if(!modalOpen())activateQuickSlot(Number(key)-1);}return}if(key==='escape'){closePanels();return}if(binds[key]){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)openPanel(binds[key]);return}if(key==='r'&&!modalOpen()){if(!e.repeat){if(p.area==='hub')toast('Zaten Ocak Köyü’ndesin.');else returnVillage();}e.preventDefault();return}if(key==='o'&&!e.repeat){$('sound').onclick();toast(sound?'Ses açıldı.':'Ses kapatıldı.');}if(key==='v'&&!e.repeat){e.preventDefault();try{const action=document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();if(action?.catch)action.catch(()=>toast('Tam ekran bu tarayıcıda kullanılamıyor.'));}catch{toast('Tam ekran bu tarayıcıda kullanılamıyor.')}}},true);
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));panelIds.forEach(id=>$(id).addEventListener('close',()=>keys={}));
$('bagButton').onclick=()=>openPanel('bag');$('guide').onclick=()=>openPanel('help');refreshBag();ui();toast('Ocak Köyü · Kontroller için H');requestAnimationFrame(frame);

